files.content:
.page {
  margin: 0;
  font-family: Helvetica, Arial, sans-serif;
  background: #000;
}

.header {
  display: flex;
  align-items: center;
  min-height: 80px;
  padding: 0 60px;
}

.header img {
  width: 200px;
}

.gallery {
  grid-template-columns: repeat(5, auto) 200px;
  grid-template-rows: repeat(6, auto);
  display: grid;
  gap: 10px;
  box-sizing: border-box;
  min-height: calc(100vh - 80px);
  padding: 0 60px 60px;
}

.gallery__item {
  box-sizing: border-box;
  margin: 0;
}

.gallery__image {
  width: 100%;
  min-height: 100%;
  max-height: 100%;
  object-fit: cover;
}
